(function(g){'use strict';
const D=g.CAMPUS_DATA,C=g.CAMPUS_CONTENT,U=g.CampusUI,M=g.CampusMath;
const {esc,fmt,fixed,badge,source,btn,link,intro,teach,note,metric,table,input,range,select,checkbox,tabs,formula,quote,lineChart,bars,question}=U;
const modelNames={RW:'Сохранить последний уровень',RT:'Осторожно продолжить тенденцию',PP:'Частично объединить информацию'};
function section(title,html,extra=''){return`<section><div class="section-heading"><h2>${title}</h2>${extra}</div>${html}</section>`;}
function helpers(text,refs=[],terms=[]){return`<aside><div class="aside-note"><h3>Что мы узнаём</h3><p>${text}</p></div>${terms.length?`<div class="aside-note"><h3>Понятия под рукой</h3>${terms.map(t=>`<p><button class="term-btn" data-action="term" data-term="${esc(t)}">${esc(t)}</button></p>`).join('')}</div>`:''}${refs.length?`<div class="aside-note"><h3>Следующий шаг</h3>${refs.map(([a,b])=>`<p><a class="inline-link" href="${a}">${b}</a></p>`).join('')}</div>`:''}</aside>`;}
function home(S){const idx=S.subsystem,ss=D.subsystems[idx];const measures=D.measures.filter(m=>C.measureToSubsystem[m.id]?.includes(idx));const mapOrder=[0,1,2,3,-1,4,5,6,7];return`<div class="hero"><div><h1>Кампус как<br>система <span>решений.</span></h1><p>Понять данные. Собрать совместимые меры. Проверить ресурсы и результат. Исследуйте адаптивно-аддитивное управление на материале одной научной работы.</p><div class="actions">${link('Пройти путь решения '+g.icon('arrow'),'#/cycle','primary')}${link('Начать с основ','#/basics')}</div><p class="tiny">Без регистрации и постоянного хранения ответов. Все учебные изменения обратимы.</p></div><div class="campus-plan"><div class="plan-head"><span>Связанные функции кампуса</span><span>Нажмите на подсистему</span></div><div class="plan-map">${mapOrder.map(i=>i<0?`<div class="plan-center">Общая задача<br>и ограничения</div>`:`<button class="plan-node ${idx===i?'active':''}" data-action="set" data-key="subsystem" data-value="${i}" aria-pressed="${idx===i}">${g.icon(['grid','home','beaker','people','heart','shield','network','target'][i])}<span>${['Помещения','Проживание','Инженерные системы','Социальные сервисы','Сопровождение','Безопасность','Цифровая среда','Доступность'][i]}</span></button>`).join('')}</div><div class="plan-note">Схема функций, не географическая карта. Один объект может участвовать в нескольких подсистемах.</div></div></div><div class="journey-strip"><div><b>69 значений</b><p>16 официальных рядов</p></div><div><b>12 мер</b><p>Паспорта и условия применения</p></div><div><b>12 стадий</b><p>От цели к следующему решению</p></div><div><b>53 формулы</b><p>Запись и понятное объяснение</p></div></div><div class="split"><div class="panel"><span class="measure-code">ПОДСИСТЕМА ${idx+1} / 8</span><h2>${esc(ss[0])}</h2><p class="case-desc">${esc(ss[1])}.</p>${teach(`<b>Важно различать:</b> ${esc(ss[2]).toLowerCase()}.`)}<p class="small muted">Содержательно связанные меры: ${measures.map(m=>`<a class="inline-link" href="#/measure/${m.id}">${m.id}</a>`).join(', ')}. Связь по теме не означает автоматического выбора меры.</p>${source('Приложение 6; § 1.1',65)}${quote('complex','§ 1.1')}</div>${helpers('Не просто количество зданий, а возможность пользоваться согласованно работающей инфраструктурой.',[['#/read/1.2','Что значит «адаптивно-аддитивная»'],['#/data','Посмотреть данные'],['#/program','Собрать программу']],['Социально-инфраструктурный комплекс','Управленческая мера'])}</div>${section('Три способа разобраться',`<a class="entry-path" href="#/read"><span class="num">01</span><div><h3>Прочитать исследование понятным языком</h3><p>Девять разделов, точные определения и короткие проверки.</p></div>${g.icon('arrow')}</a><a class="entry-path" href="#/data"><span class="num">02</span><div><h3>От числа к его смыслу</h3><p>Данные, преобразования, прогнозы, ограничения и источники.</p></div>${g.icon('arrow')}</a><a class="entry-path" href="#/cycle"><span class="num">03</span><div><h3>Провести решение через весь цикл</h3><p>M05–M06, учебное пространство M12 или ресурсосбережение M11.</p></div>${g.icon('arrow')}</a>`)}${note('<b>Граница платформы.</b> Здесь иллюстрируются данные и правила исследования. Это не цифровой двойник действующего кампуса и не подтверждение экономии от внедрения.','warning')}`;}
function dataView(S){const official=S.dataTab==='official';return intro('За каждым числом — свой смысл','Изучайте показатель вместе с определением, единицей и временем. Официальные значения и условные траектории не смешиваются.',official?'O':'EM','§ 3.1; приложение 12')+tabs('dataTab',S.dataTab,[['official','Официальные ряды'],['scenario','Условные траектории'],['match','Сопоставимость']])+(official?officialData(S):S.dataTab==='scenario'?scenarioData(S):matching(S));}
function officialData(S){const s=D.series.find(x=>x.id===S.indicator)||D.series[5];const non=s.values.filter(v=>v!==null),delta=non.at(-1)-non[0],pct=100*delta/non[0];return`<div class="controls">${select('indicator','Показатель',s.id,D.series.map(s=>[s.id,s.short]))}</div><div class="split"><div class="panel"><h2>${esc(s.short)}</h2><p class="small muted" style="margin-top:10px">${esc(s.unit)}</p>${lineChart([{name:'Значения в фиксированном наборе',values:s.values}],s.years,{title:s.definition,decimals:2,caption:'На оси — выпуски мониторинга 2021–2025. Пропуск не является нулём; линия не достраивает отсутствующие наблюдения.'})}<div class="metrics">${metric(fmt(non[0]),'Первое значение набора')}${metric(fmt(non.at(-1)),'Последнее значение')}${metric((delta>0?'+':'')+fmt(s.unit==='%'?delta:pct)+(s.unit==='%'?' п. п.':'%'),'Изменение между доступными крайними выпусками')}</div>${table(['Выпуск мониторинга','Значение', 'Единица'],s.years.map((y,i)=>[y,s.values[i]===null?'Нет записи':fmt(s.values[i],6),s.unit]),{numeric:[0,1]})}<div class="actions">${btn(g.icon('download')+' Скачать этот ряд','export-series')}${link('Построить прогноз '+g.icon('arrow'),'#/forecast','primary')}</div></div><aside><div class="aside-note"><h3>Полное определение</h3><p>${esc(s.definition)}.</p></div><div class="aside-note"><h3>Что в знаменателе</h3><p>${esc(s.unitDetail)}.</p></div><div class="aside-note"><h3>Время и происхождение</h3><p>Метка выпуска отделена от периода измерения и даты доступности. Показана фиксированная редакция, приведённая в исследовании.</p><p>${source(s.source,82)}</p></div><div class="aside-note"><h3>Граница вывода</h3><p>${['Доходы университета — не бюджет кампуса; номинальный рост не равен росту в постоянных ценах.','Фонд и обеспеченность не измеряют исправность и доступность конкретной услуги.','Количество и подключение не удостоверяют качество реального цифрового сервиса.','Университетский контекст не является непосредственным эффектом инфраструктурной меры.'][s.group]}</p></div></aside></div>${section('Два результата, которые легко перепутать',`<div class="split wide"><div class="panel"><h3>Зданий больше — помещений на студента меньше</h3><div class="metrics">${metric('+5,49%','Площадь учебно-лабораторных зданий')}${metric('−13,14%','Помещения на студента')}</div><p class="small">Между выпусками 2022 и 2025. Определения числителей различаются: отношение этих рядов не восстанавливает фактический контингент.</p>${source('§ 3.1; таблица П12.7',82)}</div><div class="panel"><h3>Компьютеров больше — доля подключения ниже</h3><div class="metrics">${metric('+27,42%','Количество компьютеров')}${metric('−1,97 п. п.','Доля с доступом к Интернету')}</div><p class="small">Рост количества оборудования не заменяет оценки обеспеченности и функциональной доступности.</p>${source('§ 3.1; таблица П12.7',82)}</div></div>`)}${teach('Сначала задайте вопрос: <b>что именно изменилось?</b> Только затем решайте, какую потребность и на каком объекте следует проверить.')}`;}
function scenarioData(S){const code=S.emIndicator;const rows=D.em.filter(r=>r.indicator.replace('Х','X')===code),cross=D.crosswalk.find(x=>x.em===code),years=Array.from({length:10},(_,i)=>2019+i),names=[...new Set(rows.map(r=>r.scenario))];const vals=names.map(name=>({name,values:years.map(y=>{let r=rows.find(r=>+r.year===y&&r.scenario===name);return r?+r.value:null;})}));return`<div class="controls">${select('emIndicator','Сценарный показатель',code,D.crosswalk.map(r=>[r.em,`${r.em} · ${r.title.slice(0,90)}`]))}</div><div class="panel"><h2>${esc(cross?.title||code)}</h2>${teach('Это <b>условные траектории в собственной шкале</b>. Даже число с меткой прошлого года не становится наблюдением.')}${lineChart(vals,years,{title:'Две условные траектории '+code,decimals:3,caption:'Шкала E/M. Названия «актуальный» и «инерционный» не задают вероятностей. Разные начальные уровни не дают причинного эффекта по разности конечных точек.'})}${table(['Метка года',...names],years.map((y,i)=>[y,...vals.map(s=>fmt(s.values[i],6))]),{numeric:[0,1,2]})}<div class="actions">${btn(g.icon('download')+' Скачать две траектории','export-em')}${link('Проверить соответствие словарей','#/data/match')}</div>${note('<b>Происхождение:</b> 420 значений перенесены из приложенной исследовательской базы. Классификация E/M и ограничения их использования приняты из окончательного текста (§ 3.1). Индивидуальные экспертные оценки и полный протокол вероятностного извлечения не представлены.','warning')}</div>`;}
function matching(S){return`${teach('Одинаковый номер — не обязательно одна и та же величина. Сначала проверьте <b>источник, определение, объект и единицу</b>.')}<div class="split wide"><div class="panel"><h3>Не совпадает</h3><p class="case-desc"><span class="inline-code">EM:X19</span> — гостиничные услуги.<br><span class="inline-code">G:X19</span> — обезличенный объект D.</p>${note('Автоматическое соединение по X19 запрещено.','error')}</div><div class="panel"><h3>Содержательно соответствует</h3><p class="case-desc"><span class="inline-code">EM:X19</span> → <span class="inline-code">G:X20</span><br>Потенциал гостиничных услуг.</p>${note('Это содержательное соответствие. Численный коэффициент перевода шкал не установлен.','warning')}</div></div>${table(['Показатель E/M','Исходное название','Код графа','Разрешённое соответствие'],D.crosswalk.map(r=>[r.em,r.title,r.graph,r.match]),{wide:true})}${source('§ 3.1; таблицы П12.3–П12.4',78)}${note('Именованные объекты не отождествляются с обезличенными вершинами по порядку. Университетский доход не пересчитывается в бюджет кампуса без отдельного основания.')}`;}
function forecastView(S){const s=D.series.find(v=>v.id===S.indicator)||D.series[5],all=M.forecastAll(D.series,S.release,S.horizon,S.kappa,S.floorFactor),f=all.find(f=>f.id===s.id&&f.model===S.model),z=f.history.z,labels=[...f.history.rows.map(r=>r.t),...Array.from({length:S.horizon},(_,i)=>'+'+(i+1))],n=z.length,med=f.history.rows.map(r=>r.v),pred=Array(n-1).fill(null).concat([med.at(-1)]),low=Array(n-1).fill(null).concat([med.at(-1)]),high=Array(n-1).fill(null).concat([med.at(-1)]);for(let h=1;h<=S.horizon;h++){let mu=z.at(-1)+h*f.drift,sd=Math.sqrt(h*f.history.q**2+h*h*f.driftVariance);pred.push(M.untransform(mu,s.transform));low.push(M.untransform(mu-1.95996398454*sd,s.transform));high.push(M.untransform(mu+1.95996398454*sd,s.transform));}const test=M.backtest(D.series);return intro('Из короткой истории — в осторожный прогноз','Три спецификации пересчитываются в браузере по 69 официальным значениям. Графовый отклик и E/M-индексы сюда не подставляются.','calculated','§ 3.1–3.2; формулы (3.6)–(3.21)')+`<div class="controls">${select('indicator','Показатель',s.id,D.series.map(s=>[s.id,s.short]))}${select('model','Модель',S.model,Object.entries(modelNames))}${select('release','История до выпуска',S.release,[2023,2024,2025])}${select('horizon','Число следующих шагов',S.horizon,[1,2,3])}</div>${S.kappa!==5||S.floorFactor!==1?note('Изменены учебные параметры: κ = '+fmt(S.kappa)+'; множитель масштабов = '+fmt(S.floorFactor)+'. Верхний прогноз относится к этому варианту. Исходные формулы и контрольное сравнение ниже сохраняют спецификацию исследования.','warning'):''}<div class="split"><div class="panel"><h2>${esc(s.short)}</h2>${lineChart([{name:'Наблюдаемый ряд',values:[...med,...Array(S.horizon).fill(null)],color:'#718572'},{name:S.model+' · медиана',values:pred,dash:true}],labels,{bands:[{low,high}],divider:n-1,title:s.short+' — наблюдения и прогноз',caption:`Затенение — маргинальный 95%-интервал. +1…+${S.horizon} — шаги после выпуска ${S.release}, не исторически выпущенный календарный прогноз.`,decimals:s.unit==='м²'?0:2})}<div class="metrics">${metric(fmt(f.median,3),'Медиана · '+esc(s.unit))}${metric(fmt(f.lo,3)+' – '+fmt(f.hi,3),'95%-интервал')}${metric(fmt(f.pBelowLast*100,1)+'%','Вероятность ниже последнего уровня — не ниже норматива')}</div>${teach(`Модель видит <b>${f.history.rows.length} уровня и ${f.history.n} изменения</b>. Она не получила дополнительных наблюдений только потому, что рассчитала много вариантов.`)}<div class="actions">${btn('Скачать результаты трёх моделей','export-forecast')}${link('Что показывает сигнал?','#/read/3.3')}${btn('Исходная спецификация','reset-forecast','','small')}</div></div>${helpers('Один показатель, его единица и неопределённость. Медиана не равна утверждённой цели, а снижение относительно последнего уровня не доказывает дефицит.',[['#/data','Вернуться к данным'],['#/mixture','Как ограничить экспертное уточнение'],['#/program','Почему прогноз не выбирает меру']],['Прогноз','Медиана','Регуляризация','Дисперсия'])}</div>${section('Проследить расчёт',`<div class="split wide"><div class="panel"><h3>1. Переводим шкалу</h3><p class="small muted" style="margin-top:10px">${s.transform==='log'?'Положительные значения → натуральный логарифм.':s.transform==='logit'?'Проценты → доля → логит.':'Средний балл сохраняется в исходной шкале.'}</p>${table(['Выпуск','Исходное значение','Преобразованное z'],f.history.rows.map((r,i)=>[r.t,fmt(r.v,6),fmt(z[i],6)]),{numeric:[0,1,2]})}${formula('3.6',true)}<h3>2. Считаем изменения и масштаб</h3>${table(['Приращение','Значение'],f.history.d.map((d,i)=>[(i+1)+' → '+(i+2),fmt(d,6)]),{numeric:[1]})}<p class="small">Абсолютный масштаб s = ${fmt(f.history.s,6)}. Квадратичный масштаб q = ${fmt(f.history.q,6)}. Нижняя граница = ${fmt(f.history.floor,3)}.</p>${formula('3.7',true)}${formula('3.8',true)}</div><div class="panel"><h3>3. Оцениваем изменение</h3><p class="case-desc">${S.model==='RW'?'RW: среднее изменение принимается равным нулю.':S.model==='RT'?`RT: сумма ${fmt(M.sum(f.history.d),6)} делится на ${f.history.n} + ${S.kappa}.`:`PP: групповой компонент ${fmt(f.groupPart,6)} и индивидуальный ${fmt(f.individualPart,6)} складываются и умножаются на s.`}</p><p class="small">Дрейф = ${fmt(f.drift,6)}; его условная дисперсия = ${fmt(f.driftVariance,6)}.</p>${formula('3.17',true)}${S.model==='PP'?formula('3.18',true):''}<h3 style="margin-top:22px">4. Строим распределение</h3><p class="case-desc">Центр в шкале z: ${fmt(z.at(-1),6)} + ${S.horizon} × ${fmt(f.drift,6)} = ${fmt(f.mu,6)}.</p><p class="small">Прогнозная дисперсия = ${fmt(f.V,6)}. Квантили переводятся обратно в ${esc(s.unit)}. Обратный образ центра — медиана, а не обязательно среднее.</p>${formula('3.19',true)}<details><summary>Изменить учебные предпосылки</summary><div class="controls">${input('kappa','Сжатие RT · κ',S.kappa,.1,50,.1)}${select('floorFactor','Множитель нижних масштабов',S.floorFactor,[[.5,'0,5'],[1,'1 · исходный'],[2,'2']])}</div><p>Значения, отличные от κ = 5 и множителя 1, создают учебный вариант. Это не опубликованный исходный расчёт.</p></details></div></div>`)}${section('Независимый пересчёт контрольного сравнения',`<p class="small muted">Здесь всегда исходные κ = 5 и нижние масштабы 0,04 / 0,20 / 2. Два прогнозных начала × 16 рядов × 3 модели = 96 прогнозов.</p>${table(['Модель','Случаев','MASE','RMSSE','CRPS*','Покрытие 80%, %','Покрытие 95%, %','Ширина / s'],test.summary.map(x=>[x.model,x.n,fmt(x.mase,3),fmt(x.rmsse,3),fmt(x.crps,3),fmt(x.coverage80,2),fmt(x.coverage95,2),fmt(x.width,3)]),{numeric:[1,2,3,4,5,6,7],wide:true})}${source('Сопоставление с таблицей 3.10',44)}${note('Числа совпадают с опубликованной таблицей после её округления. Малое преимущество RT в этом сравнении не доказывает универсального превосходства модели. Все три 95%-интервала покрыли 30 из 32 исходов.')}<details><summary>Все 96 прогнозов: история, оценка и отложенный исход</summary>${table(['Модель','Показатель','Начало','Исход','Медиана','CRPS*'],test.rows.map(r=>[r.model,r.id,r.release,fmt(r.actual,4),fmt(r.median,4),fmt(r.crps,6)]),{numeric:[2,3,4,5],wide:true})}</details>`)}${note('Исторические даты доступности каждой редакции не восстановлены. Это ретроспективная проверка фиксированного среза, а не имитация всей информации, доступной в прошлом.','warning')}`;}
function economicsView(S){const e=M.economy(D.economics,S.limits,S.p),valid=e.filter(a=>a.ok),criterion=S.criterion==='expected'?'expected':'worst',min=valid.length?Math.min(...valid.map(a=>a[criterion])):Infinity,winners=valid.filter(a=>M.near(a[criterion],min));return intro('Сначала можно. Потом — выгодно.','Пять способов исполнения из расчётного примера. Измените условия и проверьте, что исключается до сравнения стоимости.','example','§ 3.3; таблица 3.21; П16.6–П16.7')+`<div class="split"><div><div class="panel"><div class="controls">${range('p','Вероятность напряжённой нагрузки · p',S.p,0,1,.01)}${select('criterion','Критерий сравнения',S.criterion,[['expected','Ожидаемые полные затраты'],['worst','Наибольшие сценарные затраты']])}</div>${valid.length?`<p class="outcome">${winners.length===1?'Выбран вариант':'Равноценны варианты'} ${winners.map(w=>w.id).join(' и ')}</p><p class="small muted" style="margin-top:10px">${winners.map(w=>esc(w.name)).join('; ')}</p><div class="metrics">${metric(fmt(min,3),'Полные условные затраты')}${metric(valid.map(v=>v.id).join(', '),'Варианты, прошедшие все ограничения')}</div>`:note('<b>Нет допустимого варианта.</b> Запросите ресурс или измените способ исполнения. Обязательное условие не отменяется ради формального результата.','error')}${table(['Вариант','Срок: обычный / напряжённый, ч','Повторяемость','Денежный максимум','Труд, ч','Результат допуска'],e.map(a=>[a.id,a.scenarios.map(s=>s.hours).join(' / '),a.scenarios.map(s=>fmt(s.repeat,2)).join(' / '),fmt(a.cash),fmt(a.labor),a.ok?'Прошёл':a.errors.join('; ')]),{numeric:[3,4],highlights:e.map((a,i)=>winners.some(w=>w.id===a.id)?i:-1),wide:true})}${teach('Цена B ниже, но <b>независимой приёмки нет</b>. Вариант D включает больше мер, но в исходном примере не проходит трудовой лимит.')}<div class="actions">${btn('Вернуть условия исследования','reset-economy','','small')}${btn('Скачать таблицу сравнения','export-economics')}${link('Стоит ли уточнить нагрузку? '+g.icon('arrow'),'#/information','primary')}</div></div>${section('Из чего сложены затраты',table(['Вариант','Условия','Прямые','Координация','Потери пользователей','Полные'],e.flatMap(a=>a.scenarios.map((s,i)=>[a.id,i?'Напряжённые':'Обычные',s.direct,s.coord,s.loss,M.total(s)])),{numeric:[2,3,4,5],wide:true}))}${note('Денежный лимит: прямые расходы + координация. Расширенная экономическая стоимость: эти выплаты + остаточные потери пользователей. Одни и те же последствия не учитываются дважды.')}</div><aside class="panel"><h3>Условия допуска</h3><div class="controls">${input('limits.cash','Денежный лимит',S.limits.cash,0,500,1)}${input('limits.labor','Рабочее время, ч',S.limits.labor,0,150,1)}${input('limits.hours','Предельный срок, ч',S.limits.hours,0,100,1)}${input('limits.repeat','Предельная повторяемость',S.limits.repeat,0,1,.01)}</div>${note('Независимая приёмка обязательна. Её нельзя отключить ради выбора B.')}<p class="tiny muted">Новые значения полей — учебные предпосылки. Исходные: 180; 80 ч; 48 ч; 0,10.</p>${formula('2.6',true)}</aside></div>${section('Почему выбор меняется при p = 1/3',`<div class="split wide"><div class="panel">${lineChart([{name:'C · 120 + 35p',values:Array.from({length:7},(_,i)=>120+35*i/6)},{name:'E · 110 + 65p',values:Array.from({length:7},(_,i)=>110+65*i/6),dash:true}],Array.from({length:7},(_,i)=>fmt(i/6,2)),{title:'Ожидаемые затраты C и E в зависимости от вероятности',caption:'График сохраняет исходные стоимости C и E. Использовать его для выбора можно только при допустимости этих вариантов.'})}${formula('3.32',true)}</div><div class="panel"><h3>Прочитать словами</h3><p class="case-desc">У C выше исходная стоимость, но меньше дополнительные потери в напряжённом режиме. Поэтому при p &gt; 1/3 ожидаемые полные затраты C ниже.</p><p class="small">При p &lt; 1/3 дешевле E. При p = 1/3 они равноценны по принятому критерию. По наихудшему сценарию C: 155 против 175.</p>${source('§ 3.3; таблица 3.21',59)}</div></div>`)}${section('Вероятность известна только в пределах',`<div class="panel"><div class="controls">${range('pLow','Нижняя граница p',S.pLow,0,1,.01)}${range('pHigh','Верхняя граница p',S.pHigh,0,1,.01)}</div>${S.pLow>S.pHigh?note('Нижняя граница не может быть выше верхней.','error'):table(['Допустимый вариант','Максимальное сожаление'],M.regret(D.economics,S.limits,S.pLow,S.pHigh).map(r=>[r.id,fmt(r.worst,6)]),{numeric:[1]})}<p class="small muted">Сожаление — разница между стоимостью выбранного действия и лучшего действия при той же вероятности. Здесь используется интервал, а не вымышленная средняя вероятность.</p></div>`)}`;}
function informationView(S){const r=M.information(D.economics,S.limits,S.p,S.sensitivity,S.specificity,S.infoPrice,S.infoLabor,S.infoDelay);return intro('Когда информация меняет решение','Дополнительная диагностика ценна не сама по себе. Она должна изменить допустимый выбор настолько, чтобы покрыть свою стоимость.','example','§ 3.3; формулы (3.32)–(3.34); П16.7')+`<div class="controls">${range('p','Вероятность напряжённого режима',S.p,0,1,.01)}${range('sensitivity','Чувствительность сигнала',S.sensitivity,0,1,.01)}${range('specificity','Специфичность сигнала',S.specificity,0,1,.01)}${input('infoPrice','Цена диагностики',S.infoPrice,0,50,.1)}</div><div class="split"><div class="panel">${r.ok?`<h2>От сигнала к действию</h2><div class="path-list"><div class="path-step"><b>ДО УТОЧНЕНИЯ</b>p = ${fmt(S.p,3)}<br>Выбор ${r.prior.ids.join(' / ')}<br>Затраты ${fmt(r.prior.cost,3)}</div><div class="path-step"><b>ВЫСОКИЙ СИГНАЛ</b>Вероятность сигнала ${fmt(r.high,3)}<br>После него p = ${r.ph===null?'событие невозможно':fmt(r.ph,6)}<br>Выбор ${r.ah.ids.join(' / ')||'не требуется'}</div><div class="path-step"><b>НИЗКИЙ СИГНАЛ</b>Вероятность сигнала ${fmt(r.low,3)}<br>После него p = ${r.pl===null?'событие невозможно':fmt(r.pl,6)}<br>Выбор ${r.al.ids.join(' / ')||'не требуется'}</div></div><div class="metrics">${metric(fmt(r.gross,4),'Валовая ценность информации')}${metric(fmt(r.net,4),'Чистая ценность',r.net<0)}${metric(fmt(r.cost,4),'Стоимость всей стратегии')}</div>${note(r.net>1e-9?'<b>Диагностика экономически оправдана</b> при этих предпосылках.':r.net< -1e-9?'<b>Диагностика не окупает стоимость</b> по выбранному критерию.':'<b>Стратегии равноценны</b> по ожидаемым затратам.',r.net>0?'success':'warning')}${teach(`Не выбираем лучший способ заранее для неизвестного будущего. Сначала получаем <b>доступный сигнал</b>, потом применяем правило выбора.`)}<details open><summary>Весь расчёт без скрытых шагов</summary>${table(['Шаг','Расчёт / результат'],[['Высокий сигнал',`${fmt(S.p)} × ${fmt(S.sensitivity)} + (1 − ${fmt(S.p)}) × (1 − ${fmt(S.specificity)}) = ${fmt(r.high,6)}`],['Вероятность напряжения после высокого сигнала',r.ph===null?'Сигнал невозможен':`${fmt(S.p)} × ${fmt(S.sensitivity)} / ${fmt(r.high,6)} = ${fmt(r.ph,6)}`],['После низкого сигнала',r.pl===null?'Сигнал невозможен':`${fmt(S.p)} × (1 − ${fmt(S.sensitivity)}) / ${fmt(r.low,6)} = ${fmt(r.pl,6)}`],['Затраты до оплаты диагностики',`${fmt(r.high,6)} × ${fmt(r.ah.cost,6)} + ${fmt(r.low,6)} × ${fmt(r.al.cost,6)} = ${fmt(r.conditional,6)}`],['Полная стратегия',`${fmt(r.conditional,6)} + ${fmt(S.infoPrice,6)} = ${fmt(r.cost,6)}`],['Чистая ценность',`${fmt(r.prior.cost,6)} − ${fmt(r.cost,6)} = ${fmt(r.net,6)}`]])}</details>${r.restricted?note('Диагностика с заданными затратами ограничила набор доступных действий. Это сравнение изменённых стратегий; общая теорема о неотрицательной валовой ценности безусловно сюда не переносится.','warning'):''}`:note(esc(r.reason)+'. Измените ресурсные условия или способ диагностики.','error')}<div class="actions">${btn('Исходный пример: 0,4 / 0,8 / 0,8 / 2','reset-info','','primary')}${link('Изменить ограничения','#/economics')}</div></div>${helpers('При исходных условиях высокий сигнал даёт p = 8/11 и выбор C, низкий — p = 1/7 и выбор E. Полная стратегия стоит 132,8 вместо 134.',[['#/mixture','Ограничение экспертного уточнения'],['#/read/3.3','Связь с программой мер']],['Условная вероятность','Математическое ожидание','Ценность информации'])}</div>${section('Ресурсы диагностики тоже проверяются',`<div class="panel"><div class="controls">${input('infoLabor','Работа диагностики, ч',S.infoLabor,0,100,1)}${input('infoDelay','Задержка обслуживания, ч',S.infoDelay,0,100,1)}</div><p class="small muted">В исходном примере диагностика занимает 2 рабочих часа и не задерживает обслуживание. Денежные и трудовые затраты добавляются к проверке каждого исполнения. Срочную защиту нельзя откладывать ради информации.</p></div>`)}${section('Область ценности исходного сигнала',`<div class="panel">${lineChart([{name:'Валовая ценность исходного сигнала',values:Array.from({length:37},(_,i)=>Math.max(0,Math.min(18*i/36-2,8-12*i/36)))},{name:'Цена 2',values:Array(37).fill(2),dash:true}],Array.from({length:37},(_,i)=>i%6===0?fmt(i/36,2):''),{title:'Ценность информации для чувствительности и специфичности 0,8',zero:true,caption:'Фиксированный авторский пример: исходные C и E, чувствительность и специфичность 0,8. Этот график не изменяется при учебной настройке точности сигнала выше.'})}${formula('3.34')}<p class="small">При цене 2 чистая ценность положительна только при 2/9 &lt; p &lt; 1/2. На границах она нулевая. Максимум валовой ценности — 4 при p = 1/3; при цене 4 строгого выигрыша нет.</p>${formula('3.33',true)}</div>`)}`;}
function cycleView(S){const c=C.cases.find(c=>c.id===S.caseId),i=S.stage,q=c.questions[i],stage=D.stages[i],done=c.questions.filter(q=>S.mastery['case-'+q.id]==='independent').length;return intro('Двенадцать стадий одного решения','Пройдите управленческий случай: короткий вопрос, выбор действия и его основание. Это учебный разбор правил, не фактическое внедрение.','teaching',c.source)+`<div class="controls">${select('caseId','Управленческий случай',S.caseId,C.cases.map(c=>[c.id,c.title]))}</div><div class="module-map">${D.stages.map((s,k)=>`<button class="stage-btn ${i===k?'active':''} ${S.mastery['case-'+c.questions[k].id]==='independent'?'done':''}" data-action="set" data-key="stage" data-value="${k}"><span class="index">${String(k+1).padStart(2,'0')}</span>${esc(s[0].split('. ')[1].split('.')[0])}</button>`).join('')}</div><div class="split"><div class="panel"><div class="source">${esc(c.measure)} · стадия ${i+1} / 12</div><h2 style="margin-top:9px">${esc(stage[0].split('. ').slice(1).join('. '))}</h2><p class="case-desc">${esc(c.description)}</p>${teach(i===0?c.goal:i===3?c.diagnosis:`<b>В результате стадии:</b> ${esc(stage[2])}.`)}${question(q,'case-'+q.id,S)}<div class="content-nav">${btn(g.icon('back')+' Назад','stage-prev','',i===0?'small':'')}${btn(i===11?'Подвести итог':`Следующая стадия ${g.icon('arrow')}`,'stage-next','','primary')}</div></div><aside><div class="aside-note"><h3>Кто отвечает</h3><p>${esc(stage[1])}.</p></div><div class="aside-note"><h3>Что должно остаться</h3><p>${esc(stage[2])}.</p></div><div class="aside-note"><h3>Самостоятельный разбор</h3><p>${done} из 12 задач. Ответ с помощью не считается самостоятельным.</p></div><div class="aside-note"><h3>Попробовать алгоритм</h3><p><a href="#/${i<4?'data':i<7?'program':i<9?'economics':i<11?'process':'evaluation'}" class="inline-link">Открыть связанный инструмент</a></p></div></aside></div>${S.cycleSummary?`<div class="cycle-summary"><h2>Решение связывается с результатом</h2><p>В этом случае вы разобрали ${done} стадий самостоятельно. Завершение просмотра не означает освоения всех стадий. Вернитесь к тем, где понадобилась помощь.</p><p>Главное: цель → пригодные данные → допустимая программа → ресурсы → исполнение → независимая приёмка → обоснованное следующее решение.</p>${link('Проверить историю работ','#/process','lime')}</div>`:''}${quote('stage','§ 2.2')}${section('Укрупнённый цикл и подробные стадии',`<div class="panel"><p class="small">Пять фаз и восемь функциональных блоков — разные масштабы описания тех же управленческих функций. Шесть действий нормальной трассы тоже не заменяют двенадцать стадий: часть оснований может быть унаследована из действующего регламента.</p>${source('§ 1.3; § 2.1–2.3; таблица 2.5',17)}</div>`)}`;}
function processView(S){const full=S.mutation>=0?M.mutateTrace(S.mutation):M.traceScenario(S.trace),visible=S.traceStep<0?full:full.slice(0,S.traceStep),r=M.validateTrace(visible),names={register:'Регистрация',diagnose:'Диагноз',authorize:'Разрешение',execute:'Исполнение',verify:'Приёмка',close:'Закрытие',reopen:'Новый цикл',cancel:'Прекращение',knowledge:'Обучение'},actors={dispatcher:'Диспетчер',analyst:'Диагност',manager:'Уполномоченный руководитель',engineer:'Исполнитель 1',engineer2:'Исполнитель 2',inspector:'Проверяющий 1',inspector2:'Проверяющий 2'},tests=D.tables.find(t=>t.index===73).rows.slice(1);return intro('Инспектор подтверждённого исполнения','Наблюдайте, как каждое событие меняет состояние случая. Контроль не сортирует ошибочную историю и не придумывает недостающие записи.','teaching','Правила § 2.3; короткие трассы созданы для платформы')+`<div class="controls">${select('trace','История работ',S.trace,[['normal','Нормальное завершение'],['rework','Новая работа и новая приёмка'],['old','Закрытие по старой приёмке'],['self','Самоприёмка исполнителем'],['newdiagnosis','Новый диагноз без нового разрешения'],['prefix','Незавершённая работа'],['cancel','Административное прекращение'],['reopen','Повторно открытый случай']])}${select('mutation','Намеренное нарушение',S.mutation,[[-1,'Не вносить'],...tests.map((t,i)=>[i,t[0]])])}</div><div class="panel"><div class="actions">${btn('Сначала','trace-first','','small')}${btn('Следующее событие '+g.icon('arrow'),'trace-step','','primary')}${btn('Проверить всю историю','trace-all')}${btn('Скачать текущую трассу','export-trace')}</div><div class="path-list">${full.map((e,i)=>`<div class="path-step ${i<visible.length?'active':''} ${!r.ok&&i===r.index?'bad':''}"><b>${esc(e.id)} · ${Number.isFinite(e.time)?fmt(e.time)+' ч':'время неизвестно'}</b>${names[e.action]||esc(e.action)}</div>`).join('')}</div>${visible.length?note(`<b>${esc(r.status)}.</b> ${esc(r.reason)}`,r.ok?(r.complete?'success':'warning'):'error'):note('Пока нет событий. Выполните первый шаг.')}${table(['Событие','Действие','Участник','Текущее исполнение','Подтверждение','Труд цикла'],r.log.map((x,i)=>[x.event,names[x.action],actors[visible[i].actor]||visible[i].actor,x.execution||'—',x.confirmed?'Есть':'Нет',x.used]),{numeric:[5],wide:true})}${!r.ok?`<h3>Место отказа</h3><p class="case-desc">Событие ${esc(visible[r.index]?.id)}: ${esc(r.reason)}.</p>`:''}${teach('При новой работе старое подтверждение сбрасывается. <b>Положительная приёмка должна ссылаться на последнюю работу</b> и выполняться не участником исполнения текущего цикла.')}<details><summary>Исходные записи и связи</summary>${table(['Событие','Случай','Время','Версия','Основание диагноза','Решение','Исполнение / ссылка'],visible.map(e=>[e.id,e.caseId,e.time,e.rule,e.diagnosisId||e.diagnosisRef||'—',e.decisionId||e.decisionRef||'—',e.executionId||e.executionRef||'—']),{wide:true})}<p>Относительное время и имена ролей условны. В данном учебном справочнике правило v1 действует на интервале 0–72 ч. Выход за него иллюстрирует отсутствие действующей версии, а не нормативный срок реального кампуса.</p></details>${quote('accept','§ 2.3')}</div>${section('Испытать все порядки шести действий',`<div class="panel"><p class="small">Шесть разных действий можно переставить 720 способами. Здесь перебор выполняется заново на короткой учебной трассе: время остаётся возрастающим, меняется именно порядок операций.</p><div class="actions" style="margin-top:18px">${btn('Перебрать 720 порядков','permutations','','primary')}</div>${S.permutationResult?`<div class="metrics">${metric(S.permutationResult.total,'Проверено последовательностей')}${metric(S.permutationResult.accepted,'Принято нашим валидатором')}${metric(S.permutationResult.total-S.permutationResult.accepted,'Отклонено')}</div>`:''}${note('В исследовании автор также получил 1 принятую последовательность из 720. Совпадение на этом наборе не означает воспроизведения всего отсутствующего исходного журнала или универсальной безошибочности.','warning')}</div>`)}${section('Что сообщено об исходных испытаниях',`${badge('reported')}${table(['Класс нарушений','Испытаний','Отклонено'],tests,{numeric:[1,2]})}${source('Приложение 11; таблица П11.1',73)}<p class="small muted">400 отрицательных и 50 положительных авторских испытаний — опубликованный результат. Кнопка выше запускает отдельный новый тест платформы, а не эти отсутствующие трассы.</p>`)}`;}
function programView(S){const ids=S.selectedMeasures,existing=S.existing,conditions=[];const add=(title,state,why)=>conditions.push({title,state,why});add('Поставленная задача покрыта',ids.includes(S.goal)?'ok':'bad',`Для текущей учебной задачи выбран целевой модуль ${S.goal}. Пустая программа её не решает.`);if(ids.includes('M06'))add('Пригодная история для аналитической M06',existing.history?'ok':ids.includes('M05')?'pending':'bad',existing.history?'Проверяемое состояние уже существует; повторная M05 не обязательна.':ids.includes('M05')?'M05 включена как подготовка. До M06 требуется подтвердить её результат.':'Уточните историю или предусмотрите M05. Регламентная профилактика имеет другое основание.');if(ids.includes('M07'))add('Актуальная база для M07',existing.knowledge?'ok':ids.includes('M04')?'pending':'bad',existing.knowledge?'Есть пригодный актуальный источник.':ids.includes('M04')?'M04 только запланирована; актуальность её результата ещё нужно проверить.':'Нужна база проверенных правил, а не только интерфейс ассистента.');if(ids.some(x=>['M06','M11'].includes(x)))add('Доступность снабжения',existing.supply?'ok':ids.includes('M09')?'pending':'bad',existing.supply?'Действующая служба обеспечивает функцию; M09 не обязательна.':'Новая централизация не равна уже обеспеченному снабжению.');if(ids.some(x=>['M08','M11','M12'].includes(x)))add('Обязательные условия и доступность',existing.norm?'ok':'bad',existing.norm?'В этом учебном случае соответствие проверено.':'Проверка обязательна. M10 не отменяет внешние требования.');if(ids.includes('M01')&&ids.includes('M12'))add('Назначение общего помещения',!S.sameRoom?'ok':'bad',S.sameRoom?'Для одного помещения назначения конкурируют. Нужна другая конфигурация или согласованный режим.':'Указаны разные помещения; остальные ресурсы всё равно проверяются.');add('Ресурсный и календарный допуск','unknown','Фактические бюджеты, даты и нагрузки M01–M12 не заданы в источнике. Паспорта не дают численного разрешения запуска.');const bad=conditions.some(c=>c.state==='bad'),pending=conditions.some(c=>c.state==='pending');const affected=M.affectedChecks(C.checks,S.changedMeasures,S.externalChange?[S.externalChange]:[],S.registryComplete);return intro('Собрать меры — не значит сложить эффекты','Каталог сохраняет все двенадцать паспортов. Интерактив показывает отношения и предварительные проверки, не вымышленные бюджеты или причинные эффекты.','project','§ 2.1; § 3.3; приложение 13')+tabs('programTab',S.programTab,[['compose','Программа и предпосылки'],['reconfigure','Что пересогласовать'],['calendar','Общий календарный ресурс']])+(S.programTab==='calendar'?calendarView(S):S.programTab==='reconfigure'?`<div class="panel">${badge('teaching')}<h2 style="margin-top:15px">Изменение модуля затрагивает его зависимости</h2><p class="case-desc">Это небольшой учебный реестр, иллюстрирующий правило § 2.1. Он не выдаётся за полный реестр действующего кампуса.</p><div class="measure-list">${['M05','M06','M11','M12'].map(id=>`<label class="check-line"><input type="checkbox" data-action="change-measure" value="${id}" ${S.changedMeasures.includes(id)?'checked':''}>Изменена ${id}</label>`).join('')}</div><div class="controls">${select('externalChange','Внешнее основание изменилось',S.externalChange,[['','Нет'],['laborLimit','Общий трудовой лимит'],['normVersion','Обязательное требование'],['supplier','Условия снабжения'],['room','Назначение помещения']])}</div>${checkbox('registryComplete','Для учебной спецификации реестр зависимостей считается полным',S.registryComplete)}${affected.map(r=>`<div class="rule-row ${r.affected?'unknown':''}"><div class="rule-mark">${r.affected?'↻':'✓'}</div><div><b>${esc(r.title)}</b><small>${esc(r.why)}. Аргументы: ${esc(r.args.join(', '))}.</small></div></div>`).join('')}${teach('Незатронутую проверку можно сохранить <b>только если её основания не изменились</b>. Если полнота реестра не подтверждена, сокращённая проверка не имеет прежней гарантии.')}${quote('reconfigure','§ 2.1')}${formula('2.2',true)}</div>`:`<div class="controls">${select('goal','Что должна обеспечивать учебная программа',S.goal,[['M06','Аналитическая профилактика · M06'],['M12','Доступ к учебному пространству · M12'],['M11','Ресурсосбережение · M11'],['M07','Ограниченный информационный ассистент · M07']])}</div><div class="split"><div><div class="measure-list">${D.measures.map(m=>`<div class="measure-item ${ids.includes(m.id)?'selected':''}"><label><input type="checkbox" data-action="toggle-measure" value="${m.id}" ${ids.includes(m.id)?'checked':''}><span><span class="measure-code">${m.id}</span><b>${esc(m.title)}</b><p>${esc(m.role)}</p></span></label><a class="icon-btn" style="width:32px;height:32px;font-size:15px" href="#/measure/${m.id}" aria-label="Паспорт ${m.id}">↗</a></div>`).join('')}</div></div><aside class="panel"><h3>Что уже обеспечено?</h3><p class="tiny muted" style="margin-top:10px">Выбранные условия — учебные предпосылки, не наблюдения МИСИС.</p>${checkbox('existing.history','Пригодная подтверждённая история',existing.history)}${checkbox('existing.knowledge','Актуальная база правил',existing.knowledge)}${checkbox('existing.supply','Доступное снабжение',existing.supply)}${checkbox('existing.norm','Обязательное соответствие проверено',existing.norm)}${checkbox('sameRoom','M01 и M12 используют одно помещение',S.sameRoom)}${source('Отношения из таблицы 3.17',52)}</aside></div>${section('Предварительная проверка выбранной конфигурации',`<div class="panel">${note(bad?'<b>Есть невыполненные условия.</b> Пересмотрите состав или подтвердите предпосылки.':pending?'<b>Есть подготовительные меры.</b> Их включение в план не равно подтверждённому результату.':'<b>Показанные логические условия выполнены.</b> Это ещё не окончательный ресурсный допуск.',bad?'error':'warning')}${conditions.map(r=>`<div class="rule-row ${r.state==='bad'?'bad':r.state==='ok'?'':'unknown'}"><div class="rule-mark">${r.state==='ok'?'✓':r.state==='bad'?'!':'?'}</div><div><b>${esc(r.title)}</b><small>${esc(r.why)}</small></div></div>`).join('')}<div class="actions" style="margin-top:20px">${link('Числовой пример допустимости','#/economics','primary')}${btn('Скачать текущие условия и выводы','export-program')}</div></div>`)}${teach('Для аналитической M06 нужна <b>пригодная история</b>. Если она уже существует, M05 не требуется заново. Для профилактики по техническому регламенту основание другое.')}`);}
function calendarView(S){let a=S.calendar,jobs=[{start:a.start1,end:a.start1+a.duration1,load:a.load1},{start:a.start2,end:a.start2+a.duration2,load:a.load2}],r=M.intervalLoads(jobs,a.capacity),max=Math.max(...jobs.map(j=>j.end))+1,labels=Array.from({length:max+1},(_,i)=>i),vals=labels.map(t=>M.sum(jobs.filter(j=>j.start<=t&&t<j.end).map(j=>j.load)));return`<div class="panel">${badge('example')}<h2 style="margin-top:15px">Разные даты запуска ещё не означают совместимость</h2><p class="case-desc">В исходном примере два назначения общего ресурса: [1; 6) и [2; 7), нагрузка по 1, мощность 1. Имена работ и дополнительная настройка служат учебной иллюстрацией.</p><div class="controls">${input('calendar.start1','Начало работы 1',a.start1,0,12,1)}${input('calendar.duration1','Длительность 1',a.duration1,1,10,1)}${input('calendar.load1','Нагрузка 1',a.load1,0,5,.5)}</div><div class="controls">${input('calendar.start2','Начало работы 2',a.start2,0,12,1)}${input('calendar.duration2','Длительность 2',a.duration2,1,10,1)}${input('calendar.load2','Нагрузка 2',a.load2,0,5,.5)}${input('calendar.capacity','Мощность ресурса',a.capacity,0,8,.5)}</div>${lineChart([{name:'Суммарная нагрузка в начале периода',values:vals},{name:'Мощность',values:labels.map(()=>a.capacity),dash:true}],labels,{zero:true,title:'Нагрузка общего ресурса по периодам',caption:'Вычисление использует полуоткрытые интервалы. Между целыми точками нагрузка постоянна; соединяющие линии только помогают читать последовательность.'})}${note(r.ok?'Показанные назначения укладываются в ресурс.':'Пересечение создаёт превышение мощности: '+r.conflicts.map(s=>`[${s.start}; ${s.end})`).join(', ')+'.',r.ok?'success':'error')}${table(['Участок времени','Нагрузка','Мощность','Результат'],r.segments.map(s=>[`[${s.start}; ${s.end})`,fmt(s.load),fmt(a.capacity),s.load<=a.capacity?'Допустимо':'Превышение']),{numeric:[1,2]})}<div class="actions">${btn('Развести по времени: [1;6), [6;8)','calendar-fix','','primary')}${btn('Исходный конфликт','reset-calendar')}</div>${formula('3.29',true)}${formula('3.30',true)}${source('§ 2.3; пример интервальной нагрузки')}</div>`;}
function measureView(S,id){const m=D.measures.find(m=>m.id===id);if(!m)return notFound();return intro(`${m.id} · ${esc(m.title)}`,'Паспорт сохраняет содержание авторского предложения. Фактическое внедрение и численный эффект не приписываются наличию записи.','project',m.source)+`<div class="split"><div class="panel">${teach(`<b>Что меняем:</b> ${esc(m.purpose)}. <b>Как предполагается получить результат:</b> ${esc(m.fields['Исходный механизм'])}.`)}${table(['Поле паспорта','Содержание'],Object.entries(m.fields).filter(([k])=>k!=='Авторская разработка'))}<div class="actions">${btn(S.selectedMeasures.includes(id)?'Убрать из учебной программы':'Добавить в учебную программу','add-measure',`data-id="${id}"`,'primary')}${link('Вернуться к конфигурации','#/program')}</div></div>${helpers('Каждое поле отвечает на отдельный вопрос. Наличие предполагаемого механизма не означает измеренный эффект.',[['#/cycle','Пройти связанный управленческий цикл'],['#/evaluation','Как оценивать результат']],['Управленческая мера','Причинный эффект','Обратимость'])}</div>${formula('3.27',true)}`;}
function graphView(S){const e=[{from:0,to:1,weight:S.graph.w1,lag:S.graph.lag1},{from:1,to:2,weight:S.graph.w2,lag:S.graph.lag2},{from:2,to:0,weight:S.graph.feedback,lag:1}],states=M.lagSimulation(e,3,S.graph.source,12),t=S.graph.step,cert=M.certify(e,3);const labels=['Финансовые ресурсы','Снабжение','Инженерная служба'];return intro('Связи, задержки и область гарантии','Справочник исходной карты отделён от небольшой учебной сети. Полный набор авторских рёбер здесь не восстановлен.','reported','§ 2.1; § 3.2; приложения 9, 12 и 16')+tabs('graphTab',S.graphTab,[['source','Исходная карта: что известно'],['play','Как работает рекурсия'],['stability','Что означает устойчивость']])+(S.graphTab==='source'?`<div class="metrics">${metric('35','Вершин исходной карты')}${metric('331','Связь с 23 петлями')}${metric('308','Связей в топологическом расчёте')}${metric('307','Связей с известной задержкой в базовой динамике')}</div>${note('В предоставленном архиве нет полной таблицы рёбер, весов и задержек окончательной карты. Поэтому здесь нет вымышленного «точного» графа. Кнопка «Как работает рекурсия» открывает отдельно обозначенный малый пример.','warning')}<div class="split"><div class="panel"><h2>35 вершин и шесть групп</h2><div class="controls">${select('nodeGroup','Группа исходной карты',S.nodeGroup,[['all','Все группы'],...[...new Set(D.nodes.map(n=>n.group))].map(n=>[n,n])])}</div><div class="node-list">${D.nodes.filter(n=>S.nodeGroup==='all'||n.group===S.nodeGroup).map(n=>`<div class="node-row"><code>G:${esc(n.id)}</code>${esc(n.title)}<p class="tiny muted">${esc(n.group)}</p></div>`).join('')}</div></div>${helpers('Здесь шесть аналитических групп экспертного графа. Они не совпадают с восемью подсистемами кампуса или четырьмя группами официальных рядов.',[['#/data/match','Словари EM и G не совпадают'],['#/graph/play','Попробовать рекурсию']],['Граф','Вершина','Лаг','Матрица'])}</div>${section('Опубликованные результаты импульсного расчёта',`${badge('reported')}${table(D.graphImpulse[0],D.graphImpulse.slice(1),{wide:true})}${source('Таблица 3.9',43)}<p class="small muted">Показаны сообщённые автором итоги. Они не пересчитаны по отсутствующему полному реестру. Отклик нормирован; его нельзя читать как рубли, площадь или причинный эффект.</p>`)}${section('Доля связей и плотность — не одно и то же',`<div class="panel"><div class="metrics">${metric('81,49%','Межгрупповые рёбра: 251 / 308')}${metric('83,87%','Возможные межгрупповые пары: 998 / 1190')}</div><p class="small">Внутригрупповая плотность: 57/192 ≈ 0,2969. Межгрупповая: 251/998 ≈ 0,2515. Высокая доля межгрупповых рёбер сама по себе не доказывает более высокую плотность.</p>${source('§ 2.1; таблица П9.3',70)}</div>`)} `:S.graphTab==='play'?`<div class="panel">${badge('teaching')}<h2 style="margin-top:13px">Три понятия — видимый расчёт</h2>${note('Названия связаны с управлением кампусом. Связи, численные веса и их малый состав заданы для обучения; это не выделенная часть исходных 307 рёбер.','warning')}<div class="controls">${select('graph.source','Куда приложен единичный импульс',S.graph.source,labels.map((x,i)=>[i,x]))}${range('graph.step','Текущий шаг',t,0,12,1,0)}</div>${networkDiagram(labels,e,states[t])}<div class="controls">${input('graph.w1','Ресурсы → снабжение',S.graph.w1,-1.5,1.5,.05)}${select('graph.lag1','Лаг первой связи',S.graph.lag1,[0,1,2,3])}${input('graph.w2','Снабжение → служба',S.graph.w2,-1.5,1.5,.05)}${select('graph.lag2','Лаг второй связи',S.graph.lag2,[0,1,2,3])}${input('graph.feedback','Обратная связь',S.graph.feedback,-1.5,1.5,.05)}</div>${t>0?`<h3>Что вошло в шаг ${t}</h3>${table(['Связь','Используемый шаг','Вес','Исходное значение','Вклад в результат'],e.map(x=>{const index=t-1-x.lag,v=index>=0?states[index][x.from]:0;return[labels[x.from]+' → '+labels[x.to],index,fmt(x.weight,3),fmt(v,6),fmt(v*x.weight,6)];}),{numeric:[1,2,3,4]})}`:teach('Единица вводится только в начальное состояние. Потом новые внешние воздействия не добавляются.')}${lineChart(labels.map((l,i)=>({name:l,values:states.map(r=>r[i]),dash:i===1})),states.map((_,i)=>i),{title:'Свободный отклик малой учебной сети',decimals:2,caption:'Условная нормированная шкала. Прямые связи, другие пути и задержки вместе определяют полный отклик.'})}<details><summary>Все состояния</summary>${table(['Шаг',...labels],states.map((r,i)=>[i,...r.map(v=>fmt(v,8))]),{numeric:[0,1,2,3]})}</details>${formula('3.12')}<p class="small">Строка A — принимающая вершина, столбец — воздействующая. Лаг 0 передаёт из t в t+1. Вход прошлых шагов до нулевого считается нулевым.</p><div class="actions" style="margin-top:18px">${btn('Следующий шаг','graph-next','','primary')}${btn('Исходный учебный пример','reset-graph')}${link('Проверить устойчивость','#/graph/stability')}</div></div>`:`<div class="split"><div class="panel">${badge('teaching')}<h2 style="margin-top:14px">Проверяем малую текущую сеть</h2><p class="case-desc">Из весов и лагов учебной сети построена расширенная матрица. Модули весов в её верхних блоках увеличены в 1,2 раза; блоки сдвига истории не меняются.</p>${cert.ok?note(`<b>Найден численный сертификат сжатия.</b> v положителен, q = ${fmt(cert.q,8)} &lt; 1. Для этой учебной спецификации выполнены показанные неравенства.`,'success'):note('<b>Этот достаточный сертификат не найден.</b> Отрицательный результат данной конструкции сам по себе не доказывает неустойчивость.','warning')}${cert.v?table(['Компонента','v','Bv','qv','Запас'],cert.v.map((v,i)=>[i+1,fmt(v,6),fmt(cert.bv[i],6),fmt(cert.q*v,6),fmt(cert.slack[i],8)]),{numeric:[0,1,2,3,4]}):''}${formula('3.15')}<p class="small muted">Здесь применяется арифметика JavaScript с плавающей точкой. Это учебная численная проверка малой матрицы, не повторение 140 точных рациональных неравенств исходного исследования.</p><div class="actions" style="margin-top:18px">${link('Изменить учебную сеть','#/graph/play')}</div></div><aside class="panel">${badge('reported')}<h3 style="margin-top:14px">Что получено автором</h3><div class="metrics">${metric('0,506423','Спектральный радиус исходной расширенной матрицы')}${metric('140 × 140','Размер исходной системы')}${metric('0,9704535179','Коэффициент q точного сертификата')}</div><p class="small">Гарантия относится к фиксированным положениям связей и лагам, при ограничении модулей весов. Новые связи и новые задержки не покрываются автоматически.</p>${source('§ 3.2; таблица П16.3',102)}</aside></div>${teach('<b>Устойчивость модели не равна устойчивости университета.</b> Математическая гарантия говорит о затухании отклика в конкретном семействе уравнений.')}`);}
function networkDiagram(labels,edges,state){const points=[[100,64],[420,64],[260,194]];return`<svg class="chart" viewBox="0 0 520 250" role="img" aria-label="Малая учебная сеть"><title>Малая учебная сеть; веса иллюстративные</title><defs><marker id="tip" markerWidth="9" markerHeight="9" refX="8" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="none" stroke="#759b70"/></marker></defs>${edges.map(e=>{const a=points[e.from],b=points[e.to],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy),r=56;return`<line x1="${a[0]+dx/len*r}" y1="${a[1]+dy/len*28}" x2="${b[0]-dx/len*r}" y2="${b[1]-dy/len*28}" stroke="#759b70" stroke-width="2" marker-end="url(#tip)"/><text x="${(a[0]+b[0])/2+7}" y="${(a[1]+b[1])/2-10}" text-anchor="middle">${fmt(e.weight)} · лаг ${e.lag}</text>`;}).join('')}${points.map(([x,y],i)=>`<g><rect x="${x-79}" y="${y-30}" width="158" height="61" rx="12" fill="${Math.abs(state[i])>1e-10?'#e1efa9':'#eff4ec'}" stroke="#a3be91"/><text x="${x}" y="${y-5}" text-anchor="middle" style="fill:#214c3c;font-size:12px">${labels[i]}</text><text x="${x}" y="${y+17}" text-anchor="middle" style="fill:#214c3c;font-size:17px;font-weight:600">${fmt(state[i],5)}</text></g>`).join('')}</svg>`;}
function mixtureView(S){const s=D.series.find(s=>s.id==='AREA_PC'),f=M.forecastAll(D.series,2025,3,5,1).find(f=>f.id===s.id&&f.model==='RT'),mu=f.mu,V=f.V,e=Math.log(S.expertMedian),Q=S.expertVariance,w=M.expertWeight(V,Q,e-mu,S.lambda,S.mixScale,S.compatible),mix=M.mixture(mu,V,e,Q,w),lo=M.mixQuantile(.025,mu,V,e,Q,w),hi=M.mixQuantile(.975,mu,V,e,Q,w),med=M.mixQuantile(.5,mu,V,e,Q,w),threshold=Math.log(S.mixThreshold),ps=M.cdf((threshold-mu)/Math.sqrt(V)),pe=Q===0?(threshold>=e?1:0):M.cdf((threshold-e)/Math.sqrt(Q)),ph=(1-w)*ps+w*pe,min=Math.min(mu-4*Math.sqrt(V),e-4*Math.sqrt(Q)),max=Math.max(mu+4*Math.sqrt(V),e+4*Math.sqrt(Q)),xs=Array.from({length:41},(_,i)=>min+(max-min)*i/40),normal=(x,m,v)=>v===0?null:M.pdf((x-m)/Math.sqrt(v))/Math.sqrt(v);return intro('Эксперт уточняет, но не подменяет данные','Статистическая основа — RT для помещений на студента. Экспертное распределение задаётся вами как учебное предположение для той же величины.','teaching','Правило (3.22)–(3.24); исходная RT-основа из § 3.2')+`<div class="split"><div class="panel"><h2>Одна величина — два распределения</h2><p class="small muted" style="margin-top:12px">Шкала расчёта: z = ln(м² / студент). Исходная статистическая медиана ${fmt(f.median,3)} м², горизонт +3 после выпуска 2025.</p><div class="controls">${input('expertMedian','Экспертная медиана, м²/студент',S.expertMedian,1,60,.1)}${input('expertVariance','Экспертная дисперсия в z',Q,0,.5,.001)}${range('lambda','Верхний предел влияния · λ',S.lambda,0,1,.01)}${input('mixScale','Параметр расхождения · c',S.mixScale,.1,10,.1)}</div>${checkbox('compatible','Совпадают величина, объект, единица, период и шкала',S.compatible)}${!S.compatible?note('Измерительной совместимости нет: вес эксперта принудительно равен нулю.','warning'):''}${lineChart([{name:'Статистическая плотность',values:xs.map(x=>normal(x,mu,V)),color:'#5f7869'},{name:'Экспертная плотность',values:xs.map(x=>normal(x,e,Q)),dash:true,color:'#b36b36'},{name:'Полная смесь',values:xs.map(x=>(1-w)*normal(x,mu,V)+w*(normal(x,e,Q)||0)),color:'#2b6653'}],xs.map((x,i)=>i%10===0?fmt(x,2):''),{title:'Две плотности и их смесь в логарифмической шкале',zero:true,caption:Q===0?'При Q = 0 эксперт задаёт точечный исход. Он учтён в функции распределения и квантилях, но не рисуется как обычная плотность.':'Горизонтальная ось — логарифмическая шкала z. Плотность не равна вероятности отдельной точки.'})}<div class="metrics">${metric(fmt(w,6),'Фактический экспертный вес w')}${metric(fmt(Math.exp(med),3),'Медиана смеси · м²/студент')}${metric(fmt(Math.exp(lo),3)+' – '+fmt(Math.exp(hi),3),'95%-интервал полной смеси')}</div>${teach('Большое расхождение или большая неопределённость эксперта уменьшают его вес. <b>Квантили ищутся по полной смеси</b>, а не по нормальному распределению с тем же средним и дисперсией.')}${formula('3.22')}<p class="small">V = ${fmt(V,8)}; Q = ${fmt(Q,8)}; Δ = ${fmt(e-mu,8)}. Среднее смеси в z = ${fmt(mix.mean,8)}; дисперсия = ${fmt(mix.variance,8)}.</p>${formula('3.23',true)}<div class="actions" style="margin-top:18px">${btn('Вернуть учебные параметры','reset-mixture','','small')}</div></div>${helpers('Использовано правило исследования и конкретная статистическая основа. Экспертные настройки — ваши условные предпосылки, не 420 E/M-значений архива.',[['#/forecast','Проверить статистическую основу'],['#/information','Когда информация влияет на выбор']],['Распределение','Дисперсия','Квантиль','Медиана'])}</div>${section('Может ли уточнение изменить сторону порога?',`<div class="panel"><div class="controls">${input('mixThreshold','Учебная нижняя граница, м²/студент',S.mixThreshold,1,40,.1)}${range('decisionThreshold','Порог вероятности для рассмотрения',S.decisionThreshold,0,1,.01)}</div><div class="metrics">${metric(fmt(ps*100,2)+'%','Статистическая вероятность ниже границы')}${metric(fmt(ph*100,2)+'%','Вероятность после смешения')}${metric(fmt(Math.abs(ph-ps),6),'Фактическое изменение вероятности')}${metric(fmt(w,6),'Верхняя граница изменения')}</div>${note(Math.abs(ps-S.decisionThreshold)>w?'Расстояние статистической вероятности от порога больше w: эксперт не может изменить сторону порога в этой смеси.':'Расстояние до порога не больше w: достаточная гарантия сохранения стороны порога не выполнена. Реальное изменение показано выше.')}<p class="small muted">Граница и порог заданы для учебного опыта. Они не являются нормативом площади МИСИС. Вероятностный сигнал не заменяет ресурсного допуска и обоснования меры.</p></div>`)}${section('Проверка ограничителя: выигрыш имеет цену',`${badge('reported')}${table(['Смещение эксперта','Статистическая CRPS','Предлагаемая смесь CRPS','Только эксперт CRPS'],[[0,'0,954','0,925','0,901'],['0,5','0,954','0,942','1,181'],['1,5','0,954','0,992','2,965']],{numeric:[0,1,2,3]})}${source('Таблица 3.12: опубликованные имитационные итоги',46)}<p class="small muted">При полезном несмещённом сигнале ограничитель теряет часть информации; при сильном смещении защищает относительно некоторых альтернатив, но статистическая основа остаётся точнее. Полный исходный имитационный массив здесь не пересоздан.</p>`)}`;}
function evaluationView(S){const rows=D.counterfactualGaps.slice(1),col=S.gapYear==='2024'?3:2,values=rows.map(r=>M.number(r[col])),dec=M.decompose(values),toy=M.decompose([S.gap1,S.gap2]);return intro('Что именно изменилось — и почему?','Различайте исполнение, состояние, сервис и отдалённый результат университета. Хороший средний показатель может скрывать разные направления компонентов.','reported','§ 3.3; таблицы 3.19–3.20; приложение 14')+`<div class="path-list">${[['Работы','Выполнено и независимо принято'],['Объект / процесс','Готовность, простой, повторяемость'],['Сервис / пользователь','Доступ и фактическое использование'],['Университет','Отдалённый исход при отдельном механизме']].map(([a,b])=>`<div class="path-step"><b>${a}</b>${b}</div>`).join('')}</div>${teach('Открытое помещение подтверждает <b>ввод объекта</b>. Чтобы утверждать улучшение доступа, нужно проверить режим и использование. Чтобы говорить о влиянии на университет, требуется отдельное исследование.')}${section('Кампусная программа: чувствительность сравнения',`<div class="panel"><h3>Программа МГТУ — не внедрение M01–M12</h3><p class="case-desc">В сравнении использованы 8 университетов, 5 показателей и 9 календарных лет (2016–2024). Последний год включает периоды до и после открытия центрального кластера 7 сентября 2024 г.</p>${note('Полной панели 360 значений в предоставленном архиве нет. Ниже показаны опубликованные веса и разрывы; повторная подгонка синтетического аналога не выполняется.','warning')}${table(D.donors[0],D.donors.slice(1),{numeric:[2]})}${source('Таблица П14.1',95)}<div class="controls">${select('gapYear','Какие компонентные разрывы показать',S.gapYear,[['2024','Разрыв 2024'],['mean','Средний разрыв 2021–2024']])}</div>${table(['Показатель','Разрыв в стандартизованной шкале'],rows.map((r,i)=>[r[0],fmt(values[i],6)]),{numeric:[1]})}<div class="metrics">${metric(fmt(dec.mean,6),'Средний разрыв')}${metric(fmt(dec.mse,6),'Средний квадрат компонентных разрывов')}${metric(fmt(dec.aggregate,6),'Квадрат среднего разрыва')}</div><p class="small">По этой выбранной строке: ${fmt(dec.mse,6)} = ${fmt(dec.aggregate,6)} + ${fmt(dec.variance,6)}. Положительное и отрицательное отклонения частично компенсируются в среднем.</p>${source('Таблица П14.2; арифметическое разложение показанных разрывов',96)}</div>`)}${section('Смена критерия меняет вывод',`${table(D.referenceCounterfactual[0],D.referenceCounterfactual.slice(1),{numeric:[0,2,3,4],wide:true})}${source('Таблица 3.20 / П14.3',97)}${note('При нулевом штрафе подгонка только агрегата уменьшает его ошибку, но увеличивает ошибку компонентов на 28,18%. Неудовлетворительная предпериодная сопоставимость и чувствительность не дают устойчивого причинного вывода.','warning')}`)}${section('Увидеть компенсацию на двух числах',`<div class="panel">${badge('teaching')}<div class="controls">${input('gap1','Разрыв компоненты 1',S.gap1,-10,10,.1)}${input('gap2','Разрыв компоненты 2',S.gap2,-10,10,.1)}</div><div class="metrics">${metric(fmt(toy.mean,3),'Среднее')}${metric(fmt(toy.mse,3),'Средний квадрат')}${metric(fmt(toy.variance,3),'Разброс вокруг среднего')}</div><p class="small">(${fmt(S.gap1)}² + ${fmt(S.gap2)}²) / 2 = ${fmt(toy.aggregate,3)} + ${fmt(toy.variance,3)}. Среднее может быть нулевым при больших частных ошибках.</p></div>`)}${section('Как оценивать конкретную меру',`${table(D.tables.find(t=>t.index===56).rows[0],D.tables.find(t=>t.index===56).rows.slice(1),{wide:true})}${source('Таблица 3.19',56)}`)}`;}
function readView(S,id){if(!id)return intro('Исследование — от объекта к решению','Девять коротких разборов следуют организации научной работы. После объяснения можно открыть алгоритм и проверить понимание.','','Главы 1–3')+`<div class="topic-grid">${C.chapters.map(ch=>`<a href="#/read/${ch.id}" class="topic-card"><span class="num">§ ${ch.id}</span><h3>${esc(ch.title)}</h3><p>${esc(ch.lead)}</p></a>`).join('')}</div>${note('Сложные символы пока мешают? '+link('24 короткие математические основы','#/basics'))}`;const ch=C.chapters.find(x=>x.id===id);if(!ch)return notFound();const i=C.chapters.indexOf(ch);return intro(esc(ch.title),'Короткий разбор раздела '+ch.id,'',ch.source)+`<div class="split"><article class="reading panel"><p class="summary-sentence">${esc(ch.lead)}</p>${ch.parts.map(p=>`<h3>${esc(p.title)}</h3><p>${esc(p.text)}</p>`).join('')}${quote(ch.quoteKey,ch.source)}<h2>Проверить понимание</h2>${question(ch.question,'chapter-'+ch.id,S)}<div class="content-nav">${i>0?link('Предыдущий раздел','#/read/'+C.chapters[i-1].id):link('Все разделы','#/read')}${i<C.chapters.length-1?link('Дальше '+g.icon('arrow'),'#/read/'+C.chapters[i+1].id,'primary'):link('Пройти управленческий случай','#/cycle','primary')}</div></article>${helpers('Сначала сформулируйте смысл своими словами. Затем посмотрите, что делает связанный алгоритм.',[[`#/${ch.lab}`,'Открыть инструмент'],['#/formulas','Формулы исследования'],['#/glossary','Понятия простыми словами']])}</div>`;}
function basicsView(S,id){if(id){const l=C.basics.find(b=>b.id===id);if(!l)return notFound();const i=C.basics.indexOf(l);return intro(l.title,'Математический минимум в контексте кампусного управления.','teaching','Основы для чтения алгоритмов')+`<div class="split"><div class="panel reading"><p class="summary-sentence">${esc(l.explanation)}</p>${note(esc(l.example))}${question(l.question,'basic-'+l.id,S)}<div class="content-nav">${i>0?link('Назад','#/basics/'+C.basics[i-1].id):link('Все основы','#/basics')}${i<C.basics.length-1?link('Следующее понятие','#/basics/'+C.basics[i+1].id,'primary'):link('Применить в управленческом случае','#/cycle','primary')}</div></div>${helpers('Одно понятие — одно действие — одно различение. Вернитесь к примеру, если пришлось угадывать.',[[`#/${l.lab}`,'Попробовать на данных или в алгоритме'],['#/glossary','Открыть глоссарий']])}</div>`;}
const v=S.matrix,ax=[v.a*v.x+v.b*v.y,v.c*v.x+v.d*v.y],sumValue=[85,20,15].slice(S.sumStart-1,S.sumEnd).reduce((a,b)=>a+b,0);return intro('Начать без математической подготовки','Каждый символ раскрывается как понятное действие. Примеры относятся к ресурсам, данным и проверкам кампуса.','teaching','24 коротких урока')+`<div class="split wide"><div class="panel"><h2>Σ — просто сложить выбранное</h2><p class="small muted" style="margin-top:10px">Составляющие C в обычном режиме: прямые 85, координация 20, потери 15. Границы суммы ниже — учебная настройка.</p><div class="numbers">${[85,20,15].map((v,i)=>`<div class="num-tile ${i+1>=S.sumStart&&i+1<=S.sumEnd?'active':''}"><small>x${i+1}</small>${v}</div>`).join('')}</div><div class="controls">${select('sumStart','Начать с элемента',S.sumStart,[1,2,3])}${select('sumEnd','Закончить на элементе',S.sumEnd,[1,2,3])}</div>${S.sumStart>S.sumEnd?note('Для этого учебного упражнения начало должно быть не позже конца.','warning'):`<div class="equation"><math display="block"><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>${S.sumStart}</mn></mrow><mn>${S.sumEnd}</mn></munderover><msub><mi>x</mi><mi>i</mi></msub><mo>=</mo><mn>${sumValue}</mn></math></div>`}<p class="small">Полная стоимость C — сумма всех трёх компонентов. Сумма только первых двух — денежные выплаты, другая величина.</p></div><div class="panel"><h2>Матрица — несколько сумм</h2><p class="small muted" style="margin-top:10px">Две условные меры и два ресурса. Коэффициенты для обучения, не трудоёмкость авторских M05–M06.</p><div class="matrix-display"><div class="matrix">${['a','b','c','d'].map(k=>`<input type="number" data-bind="matrix.${k}" value="${v[k]}" min="0" max="9" step="1" aria-label="Коэффициент ${k}">`).join('')}</div><span>×</span><div class="matrix vector">${['x','y'].map(k=>`<input type="number" data-bind="matrix.${k}" value="${v[k]}" min="0" max="9" step="1" aria-label="План ${k}">`).join('')}</div><span>=</span><div class="matrix vector"><div class="val">${ax[0]}</div><div class="val">${ax[1]}</div></div></div><p class="small">Ресурс 1: ${v.a} × ${v.x} + ${v.b} × ${v.y} = ${ax[0]}.<br>Ресурс 2: ${v.c} × ${v.x} + ${v.d} × ${v.y} = ${ax[1]}.</p>${link('Так же устроен шаг графа','#/graph/play','small')}</div></div>${section('От простого к сложному',`<div class="topic-grid">${C.basics.map((b,i)=>`<a class="topic-card" href="#/basics/${b.id}"><span class="num">${String(i+1).padStart(2,'0')} ${S.mastery['basic-'+b.id]==='independent'?'· самостоятельно':''}</span><h3>${esc(b.title)}</h3><p>${esc(b.explanation)}</p></a>`).join('')}</div>`)}${section('Как читать символы',`<div class="symbol-grid">${C.symbols.map(([a,b])=>`<div class="symbol-card"><b>${esc(a)}</b><span>${esc(b)}</span></div>`).join('')}</div>`)}`;}
function formulasView(S,id){const list=id?D.formulas.filter(f=>f.id===id):D.formulas.filter(f=>(S.formulaGroup==='all'||f.id.startsWith(S.formulaGroup+'.'))&&(!S.formulaSearch||(f.title+' '+f.id+' '+f.explanation.join(' ')).toLowerCase().includes(S.formulaSearch.toLowerCase())));return intro('Формула — это запись действия','Все 53 нумерованные формулы перенесены из уравнений исходного Word-документа. Рядом — смысл и ссылка на связанный инструмент.','','Главы 1–3; исходная нумерация сохранена')+`<div class="controls">${select('formulaGroup','Глава',S.formulaGroup,[['all','Все главы'],['1','Глава 1'],['2','Глава 2'],['3','Глава 3']])}<label class="control">Найти формулу<input type="search" data-bind="formulaSearch" value="${esc(S.formulaSearch)}" placeholder="Например: 3.22 или вероятность"></label>${id?link('Все формулы','#/formulas'):''}</div>${teach('Неизвестный символ сначала ищите в <a class="inline-link" href="#/basics">математических основах</a>. В формуле важно понять: <b>что подаётся на вход, что с этим делают и что получается</b>.')}<div class="panel">${list.map(f=>{const n=+f.id.split('.')[1],area=f.id.startsWith('1.')?(n<=2?'read/1.1':'read/1.3'):f.id.startsWith('2.')?n>=9?'process':n>=4?'economics':'program':n<=9?'data':n<=15?'graph/play':n<=21?'forecast':n<=25?'mixture':n<=31?'program':'information';return`<article class="formula-card"><h3>(${f.id}) ${esc(f.title)}</h3><div class="equation" tabindex="0" role="region" aria-label="Формула ${f.id}">${f.math.join('')}</div><p>${f.explanation.map(esc).join(' ')}</p>${U.formulaGuide(f.id,!!id)}<div class="actions" style="margin-top:14px">${link('Связанный алгоритм','#/'+area,'small')}${!id?link('Отдельная ссылка','#/formulas/'+f.id,'small'):''}</div></article>`;}).join('')||'<p>Совпадений нет.</p>'}</div>${note('Система (2.6) включает все три математические строки. Одинаковые буквы в разных формулах могут иметь разный смысл; обозначения читаются в своей спецификации.')}`;}
function glossaryView(S,id){let terms=allTerms();if(id)terms=terms.filter(t=>t.term===id);else if(S.glossarySearch)terms=terms.filter(t=>(t.term+' '+t.definition+' '+(t.example||'')).toLowerCase().includes(S.glossarySearch.toLowerCase()));return intro('Глоссарий','Короткое объяснение, пример и точная формулировка исследования там, где она приведена.','','Понятия математики и управления')+`<div class="controls"><label class="control">Найти понятие<input type="search" data-bind="glossarySearch" value="${esc(S.glossarySearch)}" placeholder="Например: матрица, приёмка, аддитивность"></label>${id?link('Все понятия','#/glossary'):''}</div><p class="tiny muted">Показано ${terms.length} из ${allTerms().length} понятий.</p><div class="panel">${terms.map(t=>`<article class="glossary-row"><h3>${esc(t.term)}</h3><p>${esc(t.definition)}</p>${t.example?`<p class="example-text">Пример: ${esc(t.example)}</p>`:''}${t.quoteKey?quote(t.quoteKey,t.source):''}${t.source?`<p class="source">${esc(t.source)}</p>`:''}</article>`).join('')||'<p>Совпадений нет.</p>'}</div>`;}
function allTerms(){let seen=new Set();return[...C.extraTerms,...D.glossary].filter(t=>{let s=t.term.toLowerCase();if(seen.has(s))return false;seen.add(s);return true;}).sort((a,b)=>a.term.localeCompare(b.term,'ru'));}
function tableView(S,id){const selected=D.tables.find(t=>t.index===+(id??S.tableId))||D.tables.find(t=>t.index===82);return intro('Данные и таблицы исследования','Справочник исходных определений, параметров и опубликованных результатов. Таблица сохраняет свою единицу анализа и назначение.','','Таблицы основного текста и приложений')+`<div class="controls">${select('tableId','Выбрать таблицу',selected.index,D.tables.map(t=>[t.index,t.title.slice(0,170)]))}</div><div class="panel"><h2 class="table-title">${esc(selected.title)}</h2>${badge([82,76,77].includes(selected.index)?'O':[105,106,59].includes(selected.index)?'example':'reported')}${table(selected.rows[0],selected.rows.slice(1),{wide:selected.rows[0].length>3,label:selected.title})}<div class="actions">${btn('Скачать таблицу CSV','export-table',`data-id="${selected.index}"`)}${link('Как читать источники','#/sources')}</div>${note('Таблица перенесена из рукописи. Числа и текстовые оговорки не исправляются молча. «Опубликованный результат» означает результат, представленный в тексте исследования, а не обязательно внешнюю журнальную публикацию.')}</div>`;}
function sourcesView(S){return intro('Что здесь наблюдение, а что — модель','Источник и ограничения остаются рядом с результатом. Эта страница показывает состав реализации и границу её проверки.','','Учебно-исследовательская платформа')+`<div class="panel"><h2>Научная основа</h2><p class="case-desc">${esc(D.meta.author)}. «${esc(D.meta.sourceTitle)}». ${D.meta.year}. Специальность 5.2.6 — Менеджмент.</p><p class="small">Содержательная основа — предоставленная рукопись и приложенный исследовательский архив. Дословные определения отделены от учебных пояснений. Исторические организационные схемы не описывают автоматически современную штатную структуру.</p>${quote('system','§ 1.2')}<div class="metrics">${metric('69','Официальных чисел из П12.7')}${metric('420','Сценарных значений E/M из архива')}${metric('65','Справочных таблиц')}${metric('53','Формулы из исходного Word')}</div><p class="small">Первоисточник официальных рядов, указанный в исследовании: <a class="inline-link" href="${D.meta.officialURL}" target="_blank" rel="noopener">мониторинг НИТУ МИСИС</a>. На платформе используется фиксированный набор из рукописи; текущая веб-публикация не подменяет его автоматически.</p></div>${section('Разные основания — разные выводы',`<div class="panel">${table(['Метка','Что это','Что нельзя заключать'],[['Наблюдаемые данные','Фиксированные официальные значения с определением и единицей','Не превращаются в бюджет кампуса или его причинный эффект'],['Пересчёт по наблюдениям','Прогноз или производное число на наблюдаемой основе','Результат расчёта не становится новым наблюдением'],['Экспертно-модельные траектории','420 условных значений двух вариантов','Прошлая метка года не делает их фактическими наблюдениями'],['Авторский условный расчёт','Условия A–E и диагностики заданы в исследовании','Не смета и не измеренная экономия МИСИС'],['Учебная иллюстрация','Малые сети, короткие трассы, примеры и настройки платформы','Не восстановленные отсутствующие исходные данные'],['Опубликованный результат','Итог, представленный в тексте исследования','Не независимый пересчёт при отсутствии полного исходного массива'],['Проектная мера','Паспорт предложенного действия','Не факт полномасштабного внедрения']])}</div>`)}${section('Реально вычисляется в браузере',`<div class="panel"><p class="small">Преобразования и три прогноза RW / RT / PP; 96 контрольных прогнозов; точечные и вероятностные ошибки; допуск альтернатив A–E; ожидание, максимум и сожаление; условные вероятности и ценность диагностики; полная вероятностная смесь и её квантили; короткие процессные трассы и 720 перестановок; интервальная нагрузка; малый лаговый граф и численный сертификат; область повторной проверки; арифметическое разложение компонентных разрывов.</p><p class="small muted" style="margin-top:12px">Числовые вычисления платформы используют JavaScript с плавающей точкой. Точное рациональное доказательство из рукописи не заменяется округлённым выводом интерфейса.</p></div>`)}${section('Чего недостаточно для полного воспроизведения',C.missing.map(m=>`<div class="aside-note"><h3>${esc(m.name)}</h3><p>${esc(m.status)}. ${esc(m.consequence)}</p></div>`).join(''))}${section('Что намеренно не автоматизировано',`<div class="panel"><p class="small">Клики по мерам не создают произвольные коэффициенты роста благополучия, репутации или эффективности. Статистический прогноз не выбирает меру только по тематической близости. Неподтверждённая история не получает нулевые значения. Закрытие, прекращение и восстановление различаются. Успех пилота не разрешает расширение без нового допуска.</p></div>`)}${section('Сеанс и приватность',`<div class="panel"><p class="small">Нет регистрации, собственной серверной базы, аналитических счётчиков и постоянного хранения ответов. Текущие настройки и проверки существуют в оперативной памяти страницы. После перезагрузки они сбрасываются. Выгрузка CSV или отчёта выполняется только по вашей кнопке. Как у любого публичного сайта, у провайдера хостинга могут быть собственные технические журналы.</p><div class="actions" style="margin-top:16px">${btn('Очистить текущий сеанс','reset-session')}${link('Посмотреть свой разбор','#/session')}</div></div>`)}`;}
function sessionView(S){const results=Object.entries(S.mastery),ind=results.filter(([,s])=>s==='independent').length,help=results.filter(([,s])=>s==='assisted').length;return intro('Ваш текущий разбор','Отметки показывают только ответы этого сеанса. Открытие страницы или запуск графика сами по себе не означают освоение.','','После перезагрузки результаты исчезают')+`<div class="metrics">${metric(ind,'Самостоятельно решено')}${metric(help,'Разобрано с помощью')}${metric('69','Доступно содержательных проверок')}</div>${note('Ответ после показанного объяснения остаётся «с помощью». Эта отметка не превращается в сертификат или доказанную педагогическую оценку.')}${table(['Задание','Статус'],results.map(([id,v])=>[questionTitle(id),v==='independent'?'Самостоятельно':'С помощью']))}<div class="actions">${link('Продолжить управленческий случай','#/cycle','primary')}${link('Математические основы','#/basics')}${btn('Очистить сеанс','reset-session')}</div>`;}
function questionTitle(id){if(id.startsWith('case-')){for(const c of C.cases){const q=c.questions.find(q=>'case-'+q.id===id);if(q)return c.measure+' · '+q.prompt;}}if(id.startsWith('chapter-'))return'§ '+id.replace('chapter-','')+' · понимание раздела';const b=C.basics.find(b=>'basic-'+b.id===id);return b?b.title:id;}
function notFound(){return intro('Раздел не найден','Проверьте ссылку или вернитесь к обзору.')+link('Открыть кампус','#/home','primary');}
g.CampusViews={home,data:dataView,forecast:forecastView,economics:economicsView,information:informationView,cycle:cycleView,process:processView,program:programView,measure:measureView,graph:graphView,mixture:mixtureView,evaluation:evaluationView,read:readView,basics:basicsView,formulas:formulasView,glossary:glossaryView,tables:tableView,sources:sourcesView,session:sessionView,allTerms,notFound};
})(window);
